mapper.update:
UPDATE orders
status = #{status}, remark = #{remark}, pay_time = #{payTime}, finish_time = #{finishTime},
WHERE id = #{id}

UPDATE orders
SET status      = #{newStatus},
    remark      = #{remark},
    finish_time = #{finishTime}
WHERE id = #{id}
  AND status = #{expectedStatus}

mapper.select:
SELECT 
FROM orders o
WHERE o.status = 'PENDING_PAYMENT'
  AND o.create_time < #{deadline}
ORDER BY o.create_time
LIMIT #{limit}
